UPDATE papers SET authors = 'Matteo P Lisi, Salvatore Maria Aglioti, Martina Fusaro, Chiara Verga', snippet = 'Manuscript, data and analysis for: "Translating, Adapting and Validating the Touch Experiences and Attitudes Questionnaire (TEAQ) for the Italian Population"' WHERE id = 44215;

